input.command:
cd ~/cp-roles/harness-absys && python3 -c "
import json;d=json.load(open('harnesses/stages.json'))
for p in d['problems']:
  print(p['problem'], p.get('limits'), p.get('effects'), {k:v for k,v in p.items() if k not in ('subproblems','problem','file','title','limits','effects')})
  for s in p['subproblems']:
    extra={k:v for k,v in s.items() if k not in ('id','line','title','unknowns','readings','instances','stages')}
    print('  ',s['id'],s['unknowns'],[i['id']+str(i['parameters']) for i in s['instances']][:4], len(s['instances']), extra)
    for st in s['stages']:
      ex={k:v for k,v in st.items() if k not in ('stage','line','description','queries')}
      if st['commit'] or st['spawns'] or len(st['queries'])>1 or set(ex)-{'kind','commit','spawns'} or st['queries'][0].get('cap')!=20:
        print('     ',st['stage'],st['kind'],st['queries'],ex)
"

