//! An Absys session: a text, accepted an assertion at a time.
//!
//! "The on-line system is incremental in that, as assertions are accepted by
//! the system, whatever processing can be done on the basis of data already
//! present in the system is done" (Foster and Elcock 1969). So each
//! assertion is added to every derivation still alive, hibernating or not,
//! and the computation runs until every derivation hibernates or fails, or a
//! budget of steps is spent (a derivation can go on for ever; Absys's could
//! too).

use crate::compile;
use crate::machine::{Comp, Ctx, Deriv, Event, Measure, Notation, Opts, Susp, Why, V};
use crate::syntax::{self, Error, Item, Span};
use crate::syntax1969;
use std::rc::Rc;

pub const DEFAULT_BUDGET: usize = 100_000;

/// What happened when one assertion was accepted.
#[derive(Clone, Debug)]
pub struct Report {
    pub line: usize,
    pub span: Span,
    pub source: String,
    /// the events, as a range of `Session::events()`
    pub events: (usize, usize),
    pub steps: usize,
    /// the budget ran out with derivations still elaborating
    pub exhausted: bool,
    pub alive: usize,
    pub failed: usize,
    /// with `Session::measuring`: what the computation held at the end of
    /// the assertion, and the peak of each quantity while it was elaborated
    pub measure: Option<(Measure, Measure)>,
}

pub struct Session {
    pub comp: Comp,
    pub cx: Ctx,
    pub budget: usize,
    pub reports: Vec<Report>,
    /// every derivation has failed: the text is unsatisfiable
    pub dead: bool,
    /// sample `Comp::measure` after every step (measurement only)
    pub measuring: bool,
    peak: Measure,
}

impl Session {
    pub fn new(opts: Opts) -> Session {
        Session {
            comp: Comp::new(vec![Deriv::new(0)]),
            cx: Ctx::new(opts),
            budget: DEFAULT_BUDGET,
            reports: vec![],
            dead: false,
            measuring: false,
            peak: Measure::default(),
        }
    }

    pub fn notation(&self) -> Notation {
        self.cx.opts.notation
    }

    pub fn events(&self) -> &[Event] {
        &self.cx.events
    }

    /// Elaborates until every derivation hibernates or fails, or `budget` steps.
    /// Returns the steps taken and whether the budget ran out.
    pub fn run(&mut self, budget: usize) -> (usize, bool) {
        let start = self.cx.steps;
        while self.cx.steps - start < budget {
            if !self.comp.step(&mut self.cx) {
                break;
            }
            if self.measuring {
                self.peak = self.peak.max(&self.comp.measure());
            }
        }
        if self.comp.derivs.is_empty() {
            self.dead = true;
        }
        (self.cx.steps - start, self.comp.running() > 0)
    }

    /// Accepts one assertion.
    pub fn accept(&mut self, text: &str, item: &Item) -> Result<&Report, Error> {
        let p = compile::assertion(text, &item.assertion)?;
        let ev0 = self.cx.events.len();
        let failed0 = self.cx.failed.len();
        for d in &mut self.comp.derivs {
            d.assert(&p);
        }
        if self.measuring {
            self.peak = self.comp.measure();
        }
        let (steps, exhausted) = self.run(self.budget);
        let measure = self.measuring.then(|| (self.comp.measure(), self.peak));
        self.reports.push(Report {
            line: item.line,
            span: item.span,
            source: text[item.span.start..item.span.end].to_string(),
            events: (ev0, self.cx.events.len()),
            steps,
            exhausted,
            alive: self.comp.derivs.len(),
            failed: self.cx.failed.len().saturating_sub(failed0),
            measure,
        });
        Ok(self.reports.last().unwrap())
    }

    /// Reads a text and accepts each of its assertions in turn.
    pub fn load(&mut self, text: &str) -> Result<(), Error> {
        let items = parse(self.notation(), text)?;
        for item in &items {
            self.accept(text, item)?;
        }
        Ok(())
    }
}

pub fn parse(n: Notation, text: &str) -> Result<Vec<Item>, Error> {
    match n {
        Notation::Retrospective => syntax::parse(text),
        Notation::Absys1 => syntax1969::parse(text),
        Notation::Elcock1982 => syntax1969::parse_1982(text),
    }
}

/// The notation a file is in, from its name: `.ab1` is the 1969 notation,
/// `.ab2` the 1982 one.
pub fn notation_for(path: &str) -> Notation {
    if path.ends_with(".ab1") {
        Notation::Absys1
    } else if path.ends_with(".ab2") {
        Notation::Elcock1982
    } else {
        Notation::Retrospective
    }
}

/// One identifier of the text, as a query of a derivation answers it.
pub struct Answer {
    pub name: String,
    pub value: String,
    /// for a variable that is only constrained by suspended equations: the
    /// other identifiers of the text it must equal, and the equations that say so
    pub via: Vec<String>,
}

/// The answers of a derivation: every identifier of the text that is not a procedure.
pub fn answers(d: &Deriv, n: Notation) -> Vec<Answer> {
    let mut out = vec![];
    for (name, x) in &d.globals {
        if matches!(d.deref(&V::Var(*x)), V::Lam(_)) {
            continue;
        }
        let (value, via) = match d.deref(&V::Var(*x)) {
            V::Var(y) => {
                let class = equal_class(d, y);
                let others: Vec<String> = class
                    .iter()
                    .filter(|v| **v != y)
                    .filter(|v| d.globals.iter().any(|(_, g)| g == *v))
                    .map(|v| d.cells[*v as usize].name.to_string())
                    .collect();
                let eqs: Vec<String> = d
                    .waiting()
                    .filter(|s| s.why == Why::Equation && s.on.iter().any(|v| class.contains(v)))
                    .map(|s| d.show_goal(&s.goal, n))
                    .collect();
                if others.is_empty() && eqs.is_empty() {
                    (d.cells[y as usize].name.to_string(), vec![])
                } else if others.is_empty() {
                    (eqs[0].split(" = ").nth(1).unwrap_or("").to_string(), eqs)
                } else {
                    (others.join(" = "), eqs)
                }
            }
            v => (d.show(&v, n), vec![]),
        };
        out.push(Answer {
            name: name.to_string(),
            value,
            via,
        });
    }
    out
}

/// The variables a suspended equation between variables makes equal to `x`.
fn equal_class(d: &Deriv, x: u32) -> Vec<u32> {
    let mut class = vec![x];
    let mut i = 0;
    while i < class.len() {
        let v = class[i];
        for s in d.waiting().filter(|s| s.why == Why::Equation) {
            if s.on.contains(&v) {
                for w in &s.on {
                    if !class.contains(w) {
                        class.push(*w);
                    }
                }
            }
        }
        i += 1;
    }
    class
}

/// The procedures a derivation has: the identifiers instantiated to lambda expressions.
pub fn procedures(d: &Deriv) -> Vec<String> {
    d.globals
        .iter()
        .filter(|(_, x)| matches!(d.deref(&V::Var(*x)), V::Lam(_)))
        .map(|(n, _)| n.to_string())
        .collect()
}

pub fn describe_wait(d: &Deriv, s: &Susp, n: Notation) -> String {
    let g = d.show_goal(&s.goal, n);
    let on: Vec<String> =
        s.on.iter()
            .filter(|v| matches!(d.deref(&V::Var(**v)), V::Var(_)))
            .map(|v| d.cells[*v as usize].name.to_string())
            .collect();
    let why = match s.why {
        Why::Equation => return g,
        Why::Undefined => "waits for a definition",
        Why::Key => "waits for its key",
        Why::Arith => "waits for two of its numbers",
        Why::Tout => "waits for its term",
        Why::Negation => "waits for its variables",
        Why::Undecided => "cannot be decided yet; waits for",
    };
    format!("{g}  ({why}: {})", on.join(", "))
}

pub fn rc_text(s: &str) -> Rc<str> {
    Rc::from(s)
}
//! What `absys FILE` prints.

use crate::machine::{Deriv, Measure, Notation, Status};
use crate::session::{answers, describe_wait, procedures, Session};

#[derive(Clone, Copy, Default)]
pub struct Show {
    /// every event, under the assertion that caused it
    pub trace: bool,
    /// the whole binding environment of each derivation, as the retrospective writes it
    pub env: bool,
    /// the state after each assertion, not only at the end
    pub each: bool,
}

pub fn derivation(d: &Deriv, n: Notation, show: Show, out: &mut String) {
    let status = match d.status {
        Status::Hibernating => "hibernating",
        Status::Running => "still elaborating",
    };
    out.push_str(&format!("  derivation #{} ({status})\n", d.id));
    for line in &d.outputs {
        out.push_str(&format!("    output      {line}\n"));
    }
    let procs = procedures(d);
    if !procs.is_empty() {
        out.push_str(&format!("    procedures  {}\n", procs.join(", ")));
    }
    for a in answers(d, n) {
        let via = if a.via.is_empty() {
            String::new()
        } else {
            format!("   (suspended: {})", a.via.join(", "))
        };
        if a.value == a.name && a.via.is_empty() {
            out.push_str(&format!("    {}  uninstantiated\n", a.name));
        } else {
            out.push_str(&format!("    {} = {}{via}\n", a.name, a.value));
        }
    }
    let waits: Vec<String> = d.waiting().map(|s| describe_wait(d, s, n)).collect();
    if !waits.is_empty() {
        out.push_str(&format!("    suspended   {}\n", waits.join(";  ")));
    }
    let pending = d.pending(n);
    if !pending.is_empty() {
        let more = if pending.len() > 6 {
            format!(";  … {} more", pending.len() - 6)
        } else {
            String::new()
        };
        out.push_str(&format!(
            "    to do       {}{more}\n",
            pending[..pending.len().min(6)].join(";  ")
        ));
    }
    if show.env {
        let env: Vec<String> = d.environment(n).into_iter().map(|(k, v)| format!("{k}/{v}")).collect();
        out.push_str(&format!("    environment {}\n", env.join(", ")));
    }
}

pub fn state(s: &Session, show: Show, out: &mut String) {
    let n = s.notation();
    let derivs = &s.comp.derivs;
    if derivs.is_empty() {
        out.push_str("No derivation survives: the assertions are unsatisfiable.\n");
        return;
    }
    let running = s.comp.running();
    out.push_str(&format!(
        "{} derivation{}{}:\n",
        derivs.len(),
        if derivs.len() == 1 { "" } else { "s" },
        if running > 0 {
            format!(" ({running} still elaborating when the budget ran out)")
        } else {
            String::new()
        }
    ));
    let shown = if crate::machine::FULL.load(std::sync::atomic::Ordering::Relaxed) {
        usize::MAX
    } else {
        MAX_SHOWN
    };
    for d in derivs.iter().take(shown) {
        derivation(d, n, show, out);
    }
    if derivs.len() > shown {
        out.push_str(&format!("  … and {} more\n", derivs.len() - shown));
    }
}

/// The most derivations a report lists.
pub const MAX_SHOWN: usize = 24;

/// Accepts a text an assertion at a time, printing as it goes.
pub fn run(s: &mut Session, text: &str, show: Show) -> Result<String, crate::syntax::Error> {
    let items = crate::session::parse(s.notation(), text)?;
    let mut out = String::new();
    for item in &items {
        let r = s.accept(text, item)?.clone();
        if show.trace || show.each {
            out.push_str(&format!("» {}\n", r.source.replace('\n', "\n  ")));
        }
        if show.trace {
            for e in &s.events()[r.events.0..r.events.1] {
                out.push_str(&format!(
                    "  {}#{:<4} {:<9} {}\n",
                    "  ".repeat(e.depth),
                    e.deriv,
                    e.kind,
                    e.text
                ));
            }
        }
        if r.exhausted {
            out.push_str(&format!(
                "  (the budget of {} steps ran out with derivations still elaborating)\n",
                s.budget
            ));
        }
        if show.each {
            let mut st = String::new();
            state(s, show, &mut st);
            for l in st.lines() {
                out.push_str("  ");
                out.push_str(l);
                out.push('\n');
            }
            out.push('\n');
        }
    }
    if !show.each {
        state(s, show, &mut out);
    }
    Ok(out)
}

/// With `--measure`: one table row per assertion and quantity, as
/// tab-separated `line  assertion  steps  quantity  now  peak`. The peak is
/// the largest value seen after any step of that assertion: exact at the
/// granularity of steps.
pub fn measures(s: &Session) -> String {
    let mut out = String::from("line\tassertion\tsteps\tquantity\tnow\tpeak\n");
    for r in &s.reports {
        let Some((now, peak)) = r.measure else { continue };
        let src: String = r.source.split_whitespace().collect::<Vec<_>>().join(" ");
        for (k, name) in Measure::FIELDS.iter().enumerate() {
            out.push_str(&format!(
                "{}\t{}\t{}\t{}\t{}\t{}\n",
                r.line,
                src,
                r.steps,
                name,
                now.values()[k],
                peak.values()[k]
            ));
        }
    }
    out
}

//! The notation: tokens, the tree of an assertion, and the parser.
//!
//! The surface is the one Elcock's 1990 retrospective uses to present Absys,
//! which he says takes "some slight liberties ... with the original syntax"
//! (p. 3). Everything it shows is accepted: `name = lambda R, S, T body`,
//! `{…}` for a conjunction, `or`, `[X|L]` and `[1, 2]`, quoted constants
//! (`'BROWN'`), names with hyphens (`math-course`), `not(…)`, the aggregation
//! `{set(X), {…}, S}` and the output assertion `tout("U", U)`. Where it is
//! silent the choice made here is in `docs/decisions.md`.
//!
//! A text is a conjunction of assertions. Nothing separates them: an
//! assertion ends where the next token cannot continue it (a `;` may be
//! written, and is ignored). `%` starts a note that runs to the end of the
//! line; notes are not Absys.

use std::fmt;
use std::rc::Rc;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

impl Span {
    pub fn to(self, o: Span) -> Span {
        Span {
            start: self.start.min(o.start),
            end: self.end.max(o.end),
        }
    }
}

